/bin/bash -lc "cd /workspace && cat > pomodoro/core.py <<'EOF'
\"\"\"Core timer logic for the Pomodoro CLI.

The timer is a pure state machine that counts remaining seconds downward. It
never blocks or sleeps by itself; callers are responsible for the pacing (for
example, a CLI tick loop). This keeps the logic easy to test and reuse.
\"\"\"

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Iterator


class SessionType(str, Enum):
    FOCUS = \"focus\"
    SHORT_BREAK = \"short_break\"
    LONG_BREAK = \"long_break\"


@dataclass
class Session:
    type: SessionType
    duration_seconds: int
    label: str


class Timer:
    \"\"\"A countdown that switches between focus and break sessions.\"\"\"

    def __init__(
        self,
        focus_minutes: int = 25,
        short_break_minutes: int = 5,
        long_break_minutes: int = 15,
        sessions_per_cycle: int = 4,
    ) -> None:
        if focus_minutes < 1 or short_break_minutes < 1 or long_break_minutes < 1:
            raise ValueError(\"Durations must be at least 1 minute\")
        if sessions_per_cycle < 1:
            raise ValueError(\"sessions_per_cycle must be at least 1\")

        self.focus_seconds = focus_minutes * 60
        self.short_break_seconds = short_break_minutes * 60
        self.long_break_seconds = long_break_minutes * 60
        self.sessions_per_cycle = sessions_per_cycle

        self.focus_count = 0
        self._total_completed = 0
        self._remaining = self.focus_seconds
        self._session_type = SessionType.FOCUS

    @property
    def session_type(self) -> SessionType:
        return self._session_type

    @property
    def remaining(self) -> int:
        return self._remaining

    @property
    def elapsed(self) -> int:
        return self.current_duration - self._remaining

    @property
    def current_duration(self) -> int:
        return self._duration_for(self._session_type)

    @property
    def completed_sessions(self) -> int:
        return self._total_completed

    def _duration_for(self, session_type: SessionType) -> int:
        if session_type is SessionType.FOCUS:
            return self.focus_seconds
        if session_type is SessionType.SHORT_BREAK:
            return self.short_break_seconds
        return self.long_break_seconds

    def tick(self, seconds: int = 1) -> \"Session | None\":
        \"\"\"Advance the timer by "'``seconds``.

        When a session ends, it advances to the next session and returns the
        just-completed session so the caller can announce it. Returns ``None``
        otherwise.
        """
        if seconds < 1:
            raise ValueError("seconds must be at least 1")

        completed = None
        self._remaining -= seconds
        while self._remaining <= 0:
            completed = self._start_next_session(self._remaining)
        return completed

    def _start_next_session(self, overflow: int) -> Session:
        finished_type = self._session_type
        if finished_type is SessionType.FOCUS:
            self.focus_count += 1
            self._total_completed += 1
            if self.focus_count % self.sessions_per_cycle == 0:
                self._session_type = SessionType.LONG_BREAK
            else:
                self._session_type = SessionType.SHORT_BREAK
        else:
            self._session_type = SessionType.FOCUS

        self._remaining = self._duration_for(self._session_type) + overflow
        return Session(
            type=finished_type,
            duration_seconds=self._duration_for(finished_type),
            label=self._label_for(finished_type),
        )

    def _label_for(self, session_type: SessionType) -> str:
        if session_type is SessionType.FOCUS:
            return "Focus"
        if session_type is SessionType.SHORT_BREAK:
            return "Short break"
        return "Long break"

    def sessions(self) -> Iterator[Session]:
        """Yield one Session per boundary crossed by the current timer flow."""
        while True:
            yield self._start_next_session(0)

    def remaining_until(self, seconds: int) -> int:
        """Simulate ticking time forward and return time left in this session."""
        future = self._remaining - seconds
        if future > 0:
            return future
        duration = self._duration_for(self._session_type)
        return duration + (future % duration) if duration else 0


def format_time(seconds: int) -> str:
    """Format seconds as ``MM:SS``, suitable for a terminal clock."""
    seconds = max(0, int(seconds))
    return f"{seconds // 60:02d}:{seconds % 60:02d}"
EOF
echo done'

